import 'dart:convert';
import 'dart:io';

import 'package:intochat_os_flutter/intochat_os_flutter.dart';
import 'package:test/test.dart';

// The C# side owns the UI contract goldens (Flutter.Tests.Integration/Contracts, regenerated by
// `pwsh scripts/capture-all.ps1 -Out <dir> -InPlace`). This test reads those same files, so there is no
// Dart-owned copy: a C# shape change that the shell cannot read fails here after the single regenerate command.
// Core has a typed decoder only for LiveEnvelope; UI node states are read as raw maps by the ui package, so
// those records are checked for the structure the shell relies on.
final contracts = Directory(
  '${Directory.current.path}/../../tests/IntoChat.OS.Modules.Flutter.Tests.Integration/Contracts',
);

Object? golden(String file) {
  final path = File('${contracts.path}/$file');
  if (!path.existsSync()) {
    throw StateError('missing ${path.path}');
  }
  return jsonDecode(path.readAsStringSync());
}

void expectJsonValue(String where, Object? value) {
  switch (value) {
    case null || bool() || String():
      return;
    case num():
      expect(value.isFinite, isTrue, reason: '$where is not finite');
    case List():
      for (var i = 0; i < value.length; i++) {
        expectJsonValue('$where[$i]', value[i]);
      }
    case Map():
      value.forEach((k, v) {
        expect(k, isA<String>(), reason: '$where has a non-string key');
        expectJsonValue('$where.$k', v);
      });
    default:
      fail('$where holds ${value.runtimeType}');
  }
}

void expectNode(String where, Object? node) {
  expect(node, isA<Map>(), reason: '$where is not an object');
  final map = node as Map;
  expect(map['kind'], isA<int>(), reason: '$where.kind');
  expect(map['key'], isA<String>(), reason: '$where.key');
  expect(map['children'], isA<List>(), reason: '$where.children');
  final children = map['children'] as List;
  for (var i = 0; i < children.length; i++) {
    expectNode('$where.children[$i]', children[i]);
  }
}

void main() {
  final states = Map<String, dynamic>.from(
    golden('ui-states.golden.json') as Map,
  );

  test('the UI state golden is not empty', () {
    expect(states, isNotEmpty);
  });

  for (final entry in states.entries) {
    test('${entry.key} reads and re-encodes unchanged', () {
      final value = entry.value;
      expect(value, isA<Map>(), reason: '${entry.key} is not an object');
      expect((value as Map), isNotEmpty, reason: '${entry.key} is empty');
      expectJsonValue(entry.key, value);
      final encoded = jsonEncode(value);
      expect(jsonDecode(encoded), equals(value), reason: entry.key);
    });
  }

  test('the view tree decodes as nodes with kind, key and children', () {
    final view = states['IntoChat.OS.Modules.Flutter.Views.UiView'] as Map;
    expect(view['generation'], isNotNull);
    expectNode('UiView.root', view['root']);
    expectNode('UiNode', states['IntoChat.OS.Modules.Flutter.Views.UiNode']);
  });

  test('the posted UI event carries its kind, name and action', () {
    final event =
        states['IntoChat.OS.Modules.Flutter.AppUiEndpoints+UiEvent'] as Map;
    for (final field in ['kind', 'name', 'action']) {
      expect(event[field], isA<String>(), reason: 'UiEvent.$field');
    }
  });

  test('the live envelope golden decodes through LiveEnvelope', () {
    final lines = File('${contracts.path}/live-envelope.golden.json')
        .readAsLinesSync()
        .where((line) => line.trim().isNotEmpty);
    expect(lines, isNotEmpty);
    for (final line in lines) {
      final json = Map<String, dynamic>.from(jsonDecode(line) as Map);
      final envelope = LiveEnvelope.fromJson(json);
      expect(envelope.type, json['type']);
      expect(envelope.publisher, json['publisher']);
      expect(envelope.sequence, json['sequence']);
      expect(envelope.replay, json['replay'] == true);
      expect(envelope.payload, json['payload']);
    }
  });
}
